from functools import wraps
import traceback
import logging


def enter_exit_debug_logging(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            logging.debug('calling {} with {} {}'.format(func.__name__, args, kwargs))
            result = func(*args, **kwargs)
            logging.debug("output from {} is {}".format(func.__name__, result))
        except Exception as e:
            logging.debug("Exception {e} in {func}, stack is : {stack}".
                          format(e=e, func=func.__name__, stack=traceback.format_exc()))
            raise
        return result

    return wrapper
